const stats   = $('Fetch Tracker Stats').first().json;
const csvFile = $input.first().json;

// Timestamp
const now = new Date();
const p   = n => String(n).padStart(2, '0');
const timestamp = `${p(now.getDate())}/${p(now.getMonth()+1)}/${now.getFullYear()} ${p(now.getHours())}:${p(now.getMinutes())}:${p(now.getSeconds())}`;

// Global stats
const claims = stats.total_items_out;
const done   = stats.total_items_done;
const todo   = stats.total_items_todo;
const total  = stats.total_items;

// Ikata stats
const db         = stats.downloader_bytes || {};
const dc         = stats.downloader_count || {};
const ikataBytes = db['Ikata'] ?? null;
const ikataItems = dc['Ikata'] ?? null;

// Rank
const sortedBytes  = Object.values(db).sort((a, b) => b - a);
const ikataRank    = sortedBytes.filter(b => b > (ikataBytes || 0)).length + 1;
const top20Thresh  = sortedBytes[19] ?? null;
const top5Thresh   = sortedBytes[4]  ?? null;
const top1Thresh   = sortedBytes[0]  ?? null;

// Rate from CSV history
const existing = Buffer.from(csvFile.content.replace(/\n/g, ''), 'base64').toString('utf8');
const lines    = existing.trim().split('\n');
const colNames = lines[0].split(',');
const tsIdx    = colNames.indexOf('timestamp');
const byteIdx  = colNames.indexOf('ikata_bytes');

let ratePerDay = null;
if (byteIdx >= 0 && tsIdx >= 0) {
  const parseTs = s => {
    s = s.trim();
    if (s.includes('/')) {
      const [date, time = '00:00:00'] = s.split(' ');
      const [d, m, y] = date.split('/');
      return new Date(`${y}-${m.padStart(2,'0')}-${d.padStart(2,'0')}T${time.padStart(8,'0')}`);
    }
    return new Date(s);
  };
  const points = lines.slice(1)
    .map(l => l.split(','))
    .filter(c => c[byteIdx] && c[byteIdx].trim() && !isNaN(Number(c[byteIdx])))
    .map(c => ({ ts: parseTs(c[tsIdx]), bytes: Number(c[byteIdx]) }))
    .filter(pt => !isNaN(pt.ts.getTime()));
  if (points.length >= 2) {
    const elapsedSec  = (points[points.length-1].ts - points[0].ts) / 1000;
    const bytesGained = points[points.length-1].bytes - points[0].bytes;
    if (elapsedSec > 0) ratePerDay = bytesGained / elapsedSec * 86400;
  }
}

// ETA (days, static competitors assumption)
const etaDays = target => {
  if (!target || !ratePerDay || ratePerDay <= 0 || !ikataBytes) return '';
  if (ikataBytes >= target) return '0';
  return ((target - ikataBytes) / ratePerDay).toFixed(1);
};

const daysToTop20 = etaDays(top20Thresh);
const daysToTop5  = etaDays(top5Thresh);
const daysToTop1  = etaDays(top1Thresh);

// Check/update CSV header if new columns are missing
const expectedHeader = 'timestamp,claims,done,todo,total,ikata_items,ikata_bytes,ikata_rank,days_to_top20,days_to_top5,days_to_top1';
let csvBody = existing;
if (lines[0].trim() !== expectedHeader) {
  const dataLines = lines.slice(1);
  csvBody = expectedHeader + '\n' + dataLines.join('\n');
}

// Append new row
const newRow = [timestamp, claims, done, todo, total, ikataItems ?? '', ikataBytes ?? '', ikataRank, daysToTop20, daysToTop5, daysToTop1].join(',') + '\n';
const updated = csvBody.trimEnd() + '\n' + newRow;

return [{
  json: {
    sha:     csvFile.sha,
    content: Buffer.from(updated).toString('base64'),
    message: `stats: ${timestamp}`
  }
}];
